#!/usr/bin/env python3
"""One-VPS residential exit control panel. Python standard library only."""
import base64
import hmac
import html
import ipaddress
import json
import os
import pathlib
import socket
import ssl
import subprocess
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

ROOT = pathlib.Path('/etc/residential-stack')
SETTINGS = ROOT / 'settings.json'
AUTH = ROOT / 'auth.json'
STATUS = ROOT / 'status.json'
SINGBOX_CONFIG = pathlib.Path('/etc/sing-box/three-nodes.json')
LOCK = threading.RLock()


def read_json(path):
    return json.loads(path.read_text(encoding='utf-8'))


def write_json(path, data):
    temporary = path.with_name(path.name + '.tmp')
    temporary.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    temporary.chmod(0o600)
    os.replace(temporary, path)


def config_for_agent(settings):
    return {
        'mode': settings['mode'],
        'manual_node_ip': settings['manual_node_ip'],
        'proxy_port': settings['proxy_port'],
        'slot_map': {'0': settings['country']},
        'force_switch': {'0': settings['switch_revision']},
        'config_fetch_interval': settings.get('config_fetch_interval', 15),
        'heartbeat_interval': settings.get('heartbeat_interval', 30),
        'frontend_poll_interval': settings.get('frontend_poll_interval', 5),
        'youtube_check': settings.get('youtube_check', False),
    }


PAGE = base64.b64decode('').decode("utf-8")


class Handler(BaseHTTPRequestHandler):
    server_version = 'ResidentialPanel/1.0'

    def reply(self, code, value):
        data = json.dumps(value, ensure_ascii=False).encode('utf-8')
        self.send_response(code)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(data)

    def authorized(self):
        credentials = read_json(AUTH)
        expected = base64.b64encode((credentials['username'] + ':' + credentials['password']).encode()).decode()
        supplied = self.headers.get('Authorization', '')
        if not hmac.compare_digest(supplied, 'Basic ' + expected):
            self.send_response(401)
            self.send_header('WWW-Authenticate', 'Basic realm="Residential Exit Panel"')
            self.send_header('Content-Length', '0')
            self.end_headers()
            return False
        return True

    def body(self):
        size = int(self.headers.get('Content-Length', '0'))
        if size > 2_000_000 or size < 0:
            raise ValueError('请求过大')
        return json.loads(self.rfile.read(size).decode('utf-8'))

    def status(self):
        return read_json(STATUS) if STATUS.exists() else {'details': [], 'candidates': [], 'log': '', 'updated_at': 0}

    def text_reply(self, value, content_type='text/plain; charset=utf-8'):
        data = value.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdn.tailwindcss.com; style-src 'self' 'unsafe-inline'; img-src 'self' data:")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if not self.authorized(): return
        with LOCK:
            if self.path == '/api/config':
                return self.reply(200, config_for_agent(read_json(SETTINGS)))
            if self.path == '/api/status':
                return self.reply(200, self.status())
            if self.path == '/api/nodes':
                status = self.status()
                settings = read_json(SETTINGS)
                recent = time.time() - status['updated_at'] < 120
                return self.reply(200, [{'ip': settings.get('public_ip', status.get('ip', '')),
                    'details': json.dumps(status.get('details', []) if recent else []),
                    'candidates': status.get('candidates', []), 'log': status.get('log', ''),
                    'last_seen': status['updated_at'] * 1000}])
            if self.path == '/api/countries':
                codes = set('AE AR AT AU BD BE BG BH BR CA CH CL CN CO CR CY CZ DE DK DO DZ EC EE EG ES FI FR GB GE GH GR HK HR HU ID IE IL IN IQ IR IS IT JM JO JP KE KH KR KW KZ LA LB LK LT LU LV MA MD ME MK MN MO MT MU MX MY NG NI NL NO NP NZ OM PA PE PH PK PL PT QA RO RS RU SA SE SG SI SK TH TR TW UA US UY UZ VE VN ZA'.split())
                codes.update(n['country'] for n in self.status().get('candidates', []) if len(n.get('country', '')) == 2)
                return self.reply(200, sorted(codes))
            if self.path in ('/api/proxies', '/api/links'):
                links_path = ROOT / 'links.json'
                links = read_json(links_path) if links_path.exists() else {}
                if self.path == '/api/links':
                    return self.reply(200, links)
                return self.text_reply(links.get('home', '') + '\n')
            if self.path not in ('/', '/index.html'):
                return self.reply(404, {'error': '未找到'})
            settings = read_json(SETTINGS)
            credentials = read_json(AUTH)
            page = PAGE
            substitutions = {'__PANEL_URL__': f"https://{settings.get('public_ip', '')}:{settings['panel_port']}",
                '__PANEL_USER__': credentials['username'], '__PANEL_PASS__': credentials['password'],
                '__SOCKS_USER__': credentials.get('socks_username', ''), '__SOCKS_PASS__': credentials.get('socks_password', '')}
            for key, value in substitutions.items():
                page = page.replace(key, html.escape(str(value), quote=True))
            return self.text_reply(page, 'text/html; charset=utf-8')

    def do_POST(self):
        if not self.authorized(): return
        if self.headers.get('X-Panel-Action') != '1' and self.path != '/api/report':
            return self.reply(403, {'error': '缺少操作标记'})
        try:
            data = self.body()
            with LOCK:
                if self.path == '/api/report':
                    def clean_node(node, detail=False):
                        ip = str(ipaddress.IPv4Address(node.get('node_ip') if detail else node.get('ip')))
                        country = str(node.get('country', '')).upper()
                        if len(country) != 2 or not country.isascii() or not country.isalpha():
                            raise ValueError('国家代码无效')
                        if detail:
                            port = int(node['port'])
                            if not 1 <= port <= 65535: raise ValueError('端口无效')
                            return {'node_ip': ip, 'country': country, 'port': port, 'slot': 0,
                                    'connected_time': max(0, int(node.get('connected_time', 0)))}
                        return {'ip': ip, 'country': country, 'ping': max(0, int(node.get('ping', 9999)))}
                    status = {'ip': str(data.get('ip', '')), 'details': [clean_node(n, True) for n in data.get('details', [])[:1]],
                              'candidates': [clean_node(n) for n in data.get('candidates', [])[:500]],
                              'log': str(data.get('log', ''))[-24000:], 'updated_at': int(time.time())}
                    write_json(STATUS, status)
                    return self.reply(200, {'ok': True})
                settings = read_json(SETTINGS)
                if self.path == '/api/switch':
                    settings['switch_revision'] = int(time.time() * 1000)
                    write_json(SETTINGS, settings)
                    return self.reply(200, {'ok': True})
                if self.path != '/api/config':
                    return self.reply(404, {'error': '未找到'})
                country = str(data.get('country', (data.get('slot_map') or {}).get('0', ''))).upper()
                port = data.get('proxy_port')
                mode = data.get('mode')
                manual = str(data.get('manual_node_ip', '')).strip()
                if len(country) != 2 or not country.isalpha() or not country.isascii():
                    raise ValueError('国家代码必须是两个英文字母')
                if type(port) is not int or not 1 <= port <= 65535:
                    raise ValueError('端口必须在 1–65535 之间')
                if port == 80:
                    raise ValueError('TCP 80 用于正式证书的自动验证和续期，请选择其他代理端口')
                if mode not in ('auto', 'manual'):
                    raise ValueError('出口选择无效')
                if mode == 'manual':
                    ipaddress.IPv4Address(manual)
                elif manual:
                    ipaddress.IPv4Address(manual)
                new = dict(settings, country=country, proxy_port=port, mode=mode, manual_node_ip=manual)
                for name, default, minimum, maximum in [('config_fetch_interval',15,5,3600), ('heartbeat_interval',30,10,3600), ('frontend_poll_interval',5,5,300)]:
                    value = data.get(name, settings.get(name, default))
                    if type(value) is not int or not minimum <= value <= maximum:
                        raise ValueError('轮询间隔无效：' + name)
                    new[name] = value
                new['youtube_check'] = data.get('youtube_check', settings.get('youtube_check', False)) is True
                if port != settings['proxy_port']:
                    if port in (settings['panel_port'], settings.get('agent_port')):
                        raise ValueError('该端口已被管理面板使用')
                    with socket.socket() as test:
                        test.bind(('127.0.0.1', port))
                    config = read_json(SINGBOX_CONFIG)
                    old_config = json.loads(json.dumps(config))
                    next(item for item in config['outbounds'] if item['tag'] == 'home')['server_port'] = port
                    write_json(SINGBOX_CONFIG, config)
                    binary = settings.get('sing_box_bin', '/opt/residential-stack-bin/sing-box')
                    checked = subprocess.run([binary, 'check', '-c', str(SINGBOX_CONFIG)], capture_output=True, text=True, timeout=15)
                    if checked.returncode:
                        write_json(SINGBOX_CONFIG, old_config)
                        raise RuntimeError('sing-box 配置检查失败：' + checked.stderr[-300:])
                    try:
                        write_json(SETTINGS, new)
                        subprocess.run(['systemctl', 'restart', 'residential-agent.service'], check=True, timeout=20)
                        subprocess.run(['systemctl', 'restart', 'three-nodes.service'], check=True, timeout=20)
                    except Exception:
                        write_json(SETTINGS, settings)
                        write_json(SINGBOX_CONFIG, old_config)
                        subprocess.run(['systemctl', 'restart', 'residential-agent.service'], timeout=20)
                        subprocess.run(['systemctl', 'restart', 'three-nodes.service'], timeout=20)
                        raise
                else:
                    write_json(SETTINGS, new)
                return self.reply(200, {'ok': True, 'config': config_for_agent(new)})
        except Exception as exc:
            return self.reply(400, {'error': str(exc)})


def main():
    settings = read_json(SETTINGS)
    if settings.get('agent_port'):
        internal = ThreadingHTTPServer(('127.0.0.1', settings['agent_port']), Handler)
        threading.Thread(target=internal.serve_forever, daemon=True).start()
    server = ThreadingHTTPServer(('0.0.0.0', settings['panel_port']), Handler)
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    context.minimum_version = ssl.TLSVersion.TLSv1_2
    context.load_cert_chain(settings.get('public_cert', str(ROOT / 'panel-cert.pem')),
                            settings.get('public_key', str(ROOT / 'panel-key.pem')))
    server.socket = context.wrap_socket(server.socket, server_side=True)
    server.serve_forever()


if __name__ == '__main__':
    main()
